INSERT INTO `pengajuan_kredensial` (`id`, `kode_pengajuan`, `tgl_pengajuan`, `nopeg`, `unit`, `jenjang_diajukan`, `validator`, `tgl_validasi`, `status_pengajuan`, `tgl_ujian`, `penguji`, `catatan`) VALUES
(7, '20251127001', '2025-11-27 11:49:30', '12432302', 'KEPERAWATAN', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'semua berkas yang harus di upload tidak bisa terbaca, upload ulang berkasnya di sistem baru, tidak memakai berkas dari sistem yang lama, \r\nuntuk semua sertifikat isikan tgl dikeluarkan dan tanggal ed bila memnag ada'),
(32, '20251127026', '2025-11-27 14:09:13', '12472391', 'IGD', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'lengkapi data yang harus di lengkapi, tuliskan no surat/ sertifikatnya, tanggal dikeluarkan ataupun ed bila ada dan upload ulang file di sistem baru ini'),
(33, '20251127027', '2025-11-27 14:09:21', '12502397', 'ARIMBI', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'lengkapi data dari upload ulang berkas yg blm upload di sistem terbaru, lengkapi no surat, dan tanggal2 nya'),
(34, '20251127028', '2025-11-27 14:09:23', '11542297', 'IGD', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'silahkan upload ulang semua berkas dan lengkapi sesuai data isiannya no surat, tgl terbit dan ed nya'),
(40, '20251128002', '2025-11-28 10:03:20', '12532402', 'RAMA SHINTA', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'sudah tepat pengisisan hanya beberapa yang harus di lengkapi, foto background merah, kta ppni di upload ulang, sertifikat di upload, masih kosong'),
(42, '20251128004', '2025-11-28 11:04:41', '13012499', 'IBS', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'untuk kta ppni dan npwp harap di isikan tanggal pembuatan dan untuk sertifikat hipkabi apakah dobel'),
(43, '20251128005', '2025-11-28 11:54:11', '12262398', 'ARIMBI', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'upload ulang KTA PPNI dan lengkapi data dari no surat per berkas, tgl terbit dan tanggal ed bila ada'),
(44, '20251128006', '2025-11-28 11:59:07', '11592298', 'IGD', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'silahkan lengkapi data2 yang belum di isi, seperti no surat, bila ada tanggal di keluarkan dan ed bisa dilengkapi, dan  upload ulang berkas2 di sistem ini semuanya, karena bila tidak upload ulang berkas baru di sitem ini tidak akan bisa di verifikasi berkas dari sistem lama. terimakasih'),
(45, '20251129001', '2025-11-29 09:01:15', '12782496', 'KEPERAWATAN', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'lengkapi data yang sesuai, tanggal dikeluarkan dan ED yang muncul harap di tuliskan'),
(46, '20251129002', '2025-11-29 10:28:53', '13142502', 'KEPERAWATAN', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'Mohon maaf bisa lengkapi data FOTO background merah dan file KTA PPNI di isi tanggal pembuatan ataupun tanggal ED'),
(48, '20251129004', '2025-11-29 11:16:16', '12542497', 'KEPERAWATAN', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'harap melengkapi no surat, tgl dikeluarkan ataupun tanggal ED'),
(49, '20251129005', '2025-11-29 11:54:31', '12422385', 'PERISTI', '1', '4331182', '2025-12-01', 'mengulang', NULL, NULL, 'lengkapi data, so surat bila ada tanggal terbit dan tanggal ed bila ada.\r\nPelatihan BTCLS UPLOAD ULANG'),
(50, '20251129006', '2025-11-29 12:06:09', '13142502', 'KEPERAWATAN', '1', '4331182', '2025-11-29', 'mengulang', NULL, NULL, 'portofolio belum ada ttd nya\r\n'),
(51, '20251129008', '2025-11-29 13:00:43', '13012499', 'IBS', '1', '4331182', '2025-12-01', 'mengulang', NULL, NULL, 'TINGGAL MELENGKAPI DATA KTA TANGGAL BERAKIR'),
(52, '20251129009', '2025-11-29 14:17:13', '12492393', 'ARIMBI', '1', '4331182', '2025-12-01', 'mengulang', NULL, NULL, 'LENGKAPI SEMUA ISIAN DATA DARI NO SURAT DAN TANGGAL2 NYA, UNTUK PELATIHAN SILAHKAN UPLOAD BTCLS 1 SAJA, MASIH MUNCUL 2 PELATIHAN YANG SAMA'),
(53, '20251129010', '2025-11-29 15:28:22', '11542297', 'IGD', '1', '4331182', '2025-12-01', 'mengulang', NULL, NULL, 'lengkapi no2 suratnya, tanggal2 dikeluarkan dan tanggal ED nya'),
(54, '20251129011', '2025-11-29 17:51:46', '12342398', 'RAMA SHINTA', '1', NULL, NULL, 'mengulang', NULL, NULL, NULL),
(55, '20251129012', '2025-11-29 19:10:26', '12782496', 'KEPERAWATAN', '1', '4331182', '2025-12-01', 'mengulang', NULL, NULL, 'tolong lengkapi data di PPNI, tgl ED, upload ulang portofolio dan transkip nilai'),
(56, '20251129013', '2025-11-29 20:14:21', '12602499', 'IGD', '1', '4331182', '2025-12-01', 'mengulang', NULL, NULL, 'lengkapi data di PPNI tgl ED lainnya ok'),
